package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "bulkSignupWarning",
        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Derives the owner's preferred contact channel: {@code EMAIL} when an email
     * address is present (non-null and not blank), otherwise {@code PHONE}.
     */
    default String contactPreference(Owner owner) {
        String email = owner.getEmail();
        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
    }

    /**
     * Fixed city-to-region table used to derive the owner's locality.
     */
    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /**
     * Derives the owner's locality (region) from the city using the fixed
     * {@link #CITY_REGION} table, returning {@code UNKNOWN} when the city is not
     * listed.
     */
    default String locality(Owner owner) {
        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    /**
     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>}
     * where {@code YY} is the last two digits of the registration-date year
     * (e.g. {@code LON-SMI-0007-M26}). Null when either source field is absent.
     */
    default String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Single source of truth for the owner "E.164 telephone" rule. Both
 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and
 * {@link RejectDuplicateTelephone} (which compares against it) go through here, so the two
 * can never drift apart.
 *
 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country
 * code when present, otherwise assume country code {@code '+61'} and drop a single leading
 * {@code '0'} from the national digits; require 8 to 15 digits after the {@code '+'}. So
 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
 *
 * <p>For a recognised country code the national-number length is also fixed: {@code '+61'}
 * requires exactly 9 national digits and {@code '+1'} exactly 10. A number whose country
 * code is known but whose national length is wrong is rejected (returns {@code null}).
 */
final class OwnerTelephones {

    /**
     * Recognised country codes mapped to the exact number of national digits they require.
     * Ordered longest-prefix first so a leading {@code "61"} matches country {@code "61"}
     * before the shorter {@code "1"}.
     */
    private static final Map<String, Integer> NATIONAL_DIGITS = new LinkedHashMap<>();

    static {
        NATIONAL_DIGITS.put("61", 9);
        NATIONAL_DIGITS.put("1", 10);
    }

    private OwnerTelephones() {
    }

    /**
     * Converts {@code telephone} to its E.164 form, or returns {@code null} when it cannot
     * form a valid E.164 number (null input, non-digit content, fewer than 8 / more than
     * 15 digits after the {@code '+'}, or a recognised country code with the wrong
     * national-number length).
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets; any other non-digit is left in place so it
        // fails the digits check below.
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Explicit country code: keep it, drop the leading '+'.
            digits = cleaned.substring(1);
        } else {
            // No country code: assume '+61' and drop a single leading '0' from the national
            // digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        // For a recognised country code, the national-number length is fixed.
        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
            String code = country.getKey();
            if (digits.startsWith(code)) {
                int nationalLength = digits.length() - code.length();
                return nationalLength == country.getValue() ? "+" + digits : null;
            }
        }
        return "+" + digits;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Objects;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The identity of a household: the same last name and the same address. The last name is
 * compared case-insensitively with whitespace trimmed and collapsed; the address is compared
 * in its normalized form (see {@link OwnerAddresses#normalize}), so e.g. "7  elm  ave" matches
 * "7 ELM AVENUE".
 *
 * <p>Single-sources the "what is a household" definition shared by
 * {@link RejectDuplicateHousehold} (who is rejected) and {@link AssignHousehold} (who shares a
 * {@code householdId}); the two steps must agree on it, so it lives in exactly one place.
 */
final class HouseholdKey {

    private final String lastName;

    private final String address;

    private HouseholdKey(String lastName, String address) {
        this.lastName = lastName;
        this.address = address;
    }

    /** The household the given owner belongs to. */
    static HouseholdKey of(Owner owner) {
        return new HouseholdKey(normalize(owner.getLastName()), OwnerAddresses.normalize(owner.getAddress()));
    }

    /** Whether {@code owner} belongs to this household. */
    boolean matches(Owner owner) {
        return equals(of(owner));
    }

    /** Stable canonical form of the key, suitable for deriving a shared identifier. */
    String canonical() {
        return lastName + "|" + address;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof HouseholdKey other)) {
            return false;
        }
        return lastName.equals(other.lastName) && address.equals(other.address);
    }

    @Override
    public int hashCode() {
        return Objects.hash(lastName, address);
    }

    @Override
    public String toString() {
        return canonical();
    }

    /** Lower-case, trim, and collapse any run of whitespace to a single space. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a shared {@code householdId} when the request set {@code sharesHousehold} true
 * (published by {@link BuildOwner}). A household is defined by {@link HouseholdKey} — the same
 * definition {@link RejectDuplicateHousehold} uses to decide who is a duplicate.
 *
 * <p>The identifier is derived deterministically from the household key, so every owner in a
 * household computes the same value and it is stable across requests. It is assigned to this
 * (new) owner and also back-filled onto the existing same-household owner(s), so all members
 * return the same {@code householdId}.
 *
 * <p>Does nothing when {@code sharesHousehold} is not true, leaving {@code householdId} absent.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(sharesHousehold)) {
            return;
        }
        HouseholdKey household = HouseholdKey.of(owner);
        String householdId = householdId(household);
        owner.setHouseholdId(householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue;
            }
            if (household.matches(existing) && !householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }

    /** Stable id {@code H-<16 upper-hex>} derived from the household key. */
    private static String householdId(HouseholdKey household) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(household.canonical().getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return "H-" + sb;
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

@Validated
public class BuildOwner {

    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
            Out<Boolean> sharesHousehold) {
        Owner owner = ownerMapper.toOwner(request);
        // Establish the raw registration date, defaulting an absent one to the server
        // date. NormalizeOwnerRegistrationDate later rolls a weekend forward to a
        // business day; derived values (membership number, daily limit) read it back
        // off the owner, so they see the adjusted date regardless.
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        built.set(owner);
        // sharesHousehold is a create-time flag, not an Owner field; republish it for
        // RejectDuplicateHousehold. Absent in the body means false.
        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
    }
}

